// Smoke section "legacy": the v2 → v3 Durable Object compatibility boundary on the REAL running path.
//
// It starts its own `wrangler dev` (real workerd + real SQLite-backed Durable Objects, persisted in a throwaway
// directory) from scripts/wrangler.legacy.jsonc = the production Worker + one probe route, then:
//   1. creates rooms through the real API, stops wrangler, and injects AUTHENTIC v2 records (generated by the
//      deployed b1bab784 code, tests/fixtures/v2) straight into the Durable Objects' SQLite `kv`, plus due alarms;
//   2. restarts wrangler and proves /summary, /export, /ws -> 410, /init -> 409, and that the alarm fired and left
//      every kv row byte-for-byte untouched (no purge, no tick, no reschedule);
//   3. drives real Chrome: it stops reconnecting, forgets only that room's token, shows the legacy notice, and
//      "Create New Room" lands in a fresh, playable v3 room;
//   3b. Pass 6: a started v3 room whose room.status is missing and a saved v3 lobby with room.seats[1] = null (both with
//      aged `touched` and a due alarm) answer 410/410/410/409 (never 500) and keep every kv row byte-for-byte after the
//      alarm; a valid idle v3 lobby is still purged (404) and a valid active v3 match still survives its due alarm;
//   3c. Pass 7: a started v3 room whose room.status was flipped to 'lobby' while its genuine Turn 1 game row is kept
//      (Case C, aged `touched`, due alarm) and a started v3 room whose game.players[0] is null (Case D) answer
//      410/410/410/409 and keep all three kv rows byte-for-byte after the alarm; real Chrome opens Case D and shows
//      the older-version notice with zero uncaught errors;
//   3d. Pass 8: Case E (a started Turn 2 room, resolved over the real protocol, whose game.standings[0].player was set
//      to game.players.length) answers 410/410/410/409, keeps all three kv rows byte-for-byte after the due alarm and
//      shows the older-version notice in real Chrome (real seat token pre-seeded, zero uncaught errors); Case F (an
//      unstarted lobby whose `touched` text is '0x' + hex of a time 7 h ago, due alarm) is NOT purged: /summary stays
//      200 before and after the alarm and the kv rows are byte-for-byte intact;
//   4. plays a real v5 room, strips its `exportVersion` (a room persisted before the field existed), restarts,
//      and proves /export answers 409 incompatible_ruleset while the room still resumes and plays.
//
// Nothing here prints or stores a seat token or playerId: only booleans, counts and HTTP statuses.
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import http from 'node:http';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const PORT = Number(process.env.LEGACY_PORT ?? 8791);
const ORIGIN = `http://127.0.0.1:${PORT}`;
const MESSAGE = 'This room is from an older MERCADIA version — create a new room to play.';
const sha = (s) => createHash('sha256').update(s).digest('hex');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function legacySection(h) {
  const { ok, ctx, openPage, finishCtx, shot, M, endBtn, nodeReplay, RAW, pages } = h;
  const root = process.cwd();
  const persist = mkdtempSync(join(tmpdir(), 'mercadia-legacy-'));
  const doDir = join(persist, 'v3', 'do', 'mercadia-MercadiaRoom');
  const logFile = join(persist, 'wrangler.log');
  let proc = null;

  const fixture = (name) => readFileSync(join(root, 'tests', 'fixtures', 'v2', name), 'utf8');
  const V2 = { lobby: { room: fixture('lobby.room.json'), game: null }, running: { room: fixture('running.room.json'), game: fixture('running.game.json') } };

  // ── wrangler lifecycle ──
  async function start() {
    const out = [];
    proc = spawn(process.execPath, [join(root, 'node_modules', 'wrangler', 'bin', 'wrangler.js'), 'dev', '--config', 'scripts/wrangler.legacy.jsonc', '--port', String(PORT), '--ip', '127.0.0.1', '--persist-to', persist], {
      cwd: root,
      detached: true,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    proc.stdout.on('data', (d) => out.push(String(d)));
    proc.stderr.on('data', (d) => out.push(String(d)));
    proc.once('exit', () => writeFileSync(logFile, out.join('')));
    for (let i = 0; i < 120; i++) {
      try {
        const r = await fetch(`${ORIGIN}/api/health`);
        if (r.ok) return;
      } catch {
        // not up yet
      }
      await sleep(500);
    }
    throw new Error('wrangler dev (legacy) did not become healthy');
  }
  async function stop() {
    if (!proc) return;
    const p = proc;
    proc = null;
    const done = new Promise((r) => p.once('exit', r));
    try {
      process.kill(-p.pid, 'SIGTERM');
    } catch {
      // already gone
    }
    await Promise.race([done, sleep(10000)]);
    try {
      process.kill(-p.pid, 'SIGKILL');
    } catch {
      // gone
    }
    for (let i = 0; i < 40; i++) {
      try {
        await fetch(`${ORIGIN}/api/health`);
      } catch {
        break;
      }
      await sleep(250);
    }
    await sleep(2500); // workerd releases its SQLite locks a moment after the HTTP port closes
  }

  /** Run a write against a Durable Object file, waiting out any lingering lock from the stopped workerd. */
  async function withRetry(fn) {
    let last;
    for (let i = 0; i < 30; i++) {
      try {
        return fn();
      } catch (e) {
        last = e;
        if (!/locked|busy/i.test(String(e.message))) throw e;
        await sleep(500);
      }
    }
    throw last;
  }

  // ── storage helpers (the Durable Object's own SQLite files) ──
  const roomFiles = () => readdirSync(doDir).filter((f) => f.endsWith('.sqlite') && f !== 'metadata.sqlite');
  function fileFor(code) {
    for (const f of roomFiles()) {
      const db = new DatabaseSync(join(doDir, f), { readOnly: true });
      try {
        const n = db.prepare('SELECT * FROM __miniflare_do_name').get();
        if (n && Object.values(n).includes(code)) return f;
      } catch {
        // not a room file
      } finally {
        db.close();
      }
    }
    return null;
  }
  function kvRows(file) {
    const db = new DatabaseSync(join(doDir, file), { readOnly: true });
    try {
      return db.prepare('SELECT k, v FROM kv ORDER BY k').all().map((r) => ({ k: r.k, v: r.v }));
    } finally {
      db.close();
    }
  }
  const digest = (rows) => [...rows].sort((x, y) => (x.k < y.k ? -1 : 1)).map((r) => `${r.k}:${r.v.length}:${sha(r.v)}`).join('|');
  function alarmPending(file) {
    const db = new DatabaseSync(join(doDir, file), { readOnly: true });
    try {
      // workerd clears a fired alarm by nulling its stored time; a pending alarm holds a time.
      return Number(db.prepare('SELECT count(*) AS n FROM _cf_METADATA WHERE key = 1 AND value IS NOT NULL').get().n) > 0;
    } finally {
      db.close();
    }
  }
  async function writeRows(file, rows, alarmAtMs) {
    return withRetry(() => writeRowsNow(file, rows, alarmAtMs));
  }
  function writeRowsNow(file, rows, alarmAtMs) {
    const db = new DatabaseSync(join(doDir, file));
    try {
      db.exec('DELETE FROM kv');
      const ins = db.prepare('INSERT INTO kv (k, v) VALUES (?, ?)');
      for (const [k, v] of rows) ins.run(k, v);
      if (alarmAtMs) {
        const ns = BigInt(alarmAtMs) * 1000000n;
        db.prepare('UPDATE _cf_METADATA SET value = ? WHERE key = 1').run(ns);
      }
    } finally {
      db.close();
    }
    if (alarmAtMs) {
      const m = new DatabaseSync(join(doDir, 'metadata.sqlite'));
      try {
        m.prepare('UPDATE _cf_ALARM SET scheduled_time = ? WHERE actor_id = ?').run(BigInt(alarmAtMs) * 1000000n, file.replace(/\.sqlite$/, ''));
      } finally {
        m.close();
      }
    }
  }
  async function patchRoomRow(file, fn) {
    return withRetry(() => patchRoomRowNow(file, fn));
  }
  function patchRoomRowNow(file, fn) {
    const db = new DatabaseSync(join(doDir, file));
    try {
      const row = db.prepare("SELECT v FROM kv WHERE k = 'room'").get();
      const room = JSON.parse(row.v);
      fn(room);
      db.prepare("UPDATE kv SET v = ? WHERE k = 'room'").run(JSON.stringify(room));
    } finally {
      db.close();
    }
  }

  // ── network helpers ──
  const get = async (path, init) => {
    const res = await fetch(`${ORIGIN}${path}`, init);
    let body = null;
    try {
      body = await res.json();
    } catch {
      body = null;
    }
    return { status: res.status, body, headers: res.headers };
  };
  const rawUpgradeStatus = (code) =>
    new Promise((resolve) => {
      const req = http.request({ host: '127.0.0.1', port: PORT, path: `/ws/rooms/${code}`, headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': 'dGhlIHNhbXBsZSBub25jZQ==' } });
      req.on('response', (res) => {
        res.resume();
        resolve({ status: res.statusCode, upgraded: false });
      });
      req.on('upgrade', (res, socket) => {
        socket.destroy();
        resolve({ status: res.statusCode, upgraded: true });
      });
      req.on('error', () => resolve({ status: 0, upgraded: false }));
      req.end();
    });

  /** A minimal real WebSocket seat (Node's built-in WebSocket) for driving a v5 room through the real protocol. */
  function seat(code, playerId) {
    const ws = new WebSocket(`ws://127.0.0.1:${PORT}/ws/rooms/${code}`);
    const inbox = [];
    const waiters = [];
    ws.addEventListener('message', (ev) => {
      const m = JSON.parse(ev.data);
      inbox.push(m);
      for (const w of [...waiters]) if (w.pred(m)) (waiters.splice(waiters.indexOf(w), 1), w.res(m));
    });
    const next = (pred, ms = 15000) =>
      new Promise((res, rej) => {
        const hit = inbox.find(pred);
        if (hit) return res(hit);
        const t = setTimeout(() => rej(new Error('seat: timed out')), ms);
        waiters.push({ pred, res: (m) => (clearTimeout(t), res(m)) });
      });
    const opened = new Promise((res, rej) => {
      ws.addEventListener('open', res, { once: true });
      ws.addEventListener('error', () => rej(new Error('seat: socket error')), { once: true });
    });
    return {
      ws,
      inbox,
      next,
      send: (m) => ws.send(JSON.stringify(m)),
      hello: async (name) => {
        await opened;
        ws.send(JSON.stringify({ t: 'hello', name, playerId }));
        return next((m) => m.t === 'welcome');
      },
      close: () => ws.close(),
    };
  }

  // The three rooms: a v2 lobby, a v2 running match, and a real v5 room (later stripped of exportVersion).
  let LA, LB, PV, CA, CB, PL, PA, CC, CD, CE, CF;
  let pvSeat = null; // the real room's seat id, held in memory only, never printed
  let ceSeat = null; // Case E's real seat id, held in memory only, never printed
  let before = {};
  try {
    // ───────── phase 1: create rooms through the real API ─────────
    await start();
    const mk = async () => (await get('/api/rooms', { method: 'POST' })).body.code;
    LA = await mk();
    LB = await mk();
    PV = await mk();
    CA = await mk();
    CB = await mk();
    PL = await mk();
    PA = await mk();
    CC = await mk();
    CD = await mk();
    CE = await mk();
    CF = await mk();
    ok(new Set([LA, LB, PV, CA, CB, PL, PA, CC, CD, CE, CF]).size === 11 && [LA, LB, PV, CA, CB, PL, PA, CC, CD, CE, CF].every((c) => /^[A-Z]{4}$/.test(c)), 'legacy: eleven rooms opened through POST /api/rooms on a fresh persisted wrangler dev');

    // PV: a real v5 match driven over the real protocol, one turn resolved, then exported and replayed.
    {
      const s = seat(PV);
      const w = await s.hello('Ada');
      pvSeat = w.playerId;
      s.send({ t: 'start' });
      const st = await s.next((m) => m.t === 'state');
      s.send({ t: 'draft', turn: st.turn, revision: 1, orders: [{ t: 'borrow' }] });
      await s.next((m) => m.t === 'draftAck' && m.revision === 1);
      s.send({ t: 'ready', turn: st.turn, revision: 1, epoch: 0 });
      await s.next((m) => m.t === 'resolved');
      s.close();
      await sleep(400);
      const exp = await get(`/api/rooms/${PV}/export`);
      writeFileSync(join(RAW, 'legacy-pv-v5-export.json'), JSON.stringify(exp.body));
      const rp = nodeReplay(join(RAW, 'legacy-pv-v5-export.json'));
      ok(exp.status === 200 && exp.body?.version === 5 && exp.body.log.length === 1 && rp.ok && rp.turnsReplayed === 1 && rp.mismatches.length === 0, 'export guard: a room started under version 5 exports 200 as version 5 and replays bit-for-bit (exit 0)', `http=${exp.status} version=${exp.body?.version} replay=${JSON.stringify({ ok: rp.ok, n: rp.turnsReplayed })}`);
    }
    // CA and PA: real started v3 matches (Turn 1 planning), driven over the real protocol.
    for (const code of [CA, PA, CC, CD]) {
      const s1 = seat(code);
      await s1.hello('Ada');
      s1.send({ t: 'start' });
      await s1.next((m) => m.t === 'state');
      s1.close();
    }
    // CE: a real started room driven over the real protocol through Turn 1 into Turn 2 planning (Pass 8 Case E).
    {
      const s = seat(CE);
      const w = await s.hello('Ada');
      ceSeat = w.playerId;
      s.send({ t: 'start' });
      const st = await s.next((m) => m.t === 'state');
      s.send({ t: 'draft', turn: st.turn, revision: 1, orders: [{ t: 'borrow' }] });
      await s.next((m) => m.t === 'draftAck' && m.revision === 1);
      s.send({ t: 'ready', turn: st.turn, revision: 1, epoch: 0 });
      const res = await s.next((m) => m.t === 'resolved');
      ok(res.turn === 2, 'Pass 8 Case E: the base room was resolved through Turn 1 over the real WebSocket protocol and is planning Turn 2', `turn=${res.turn}`);
      s.close();
    }
    await sleep(400);
    const pvFile = fileFor(PV);
    const pvRoom = JSON.parse(kvRows(pvFile).find((r) => r.k === 'room').v);
    ok(pvRoom.exportVersion === 5 && pvRoom.lastResolved === 1, 'export guard: the persisted room records exportVersion 5 when its match starts', `exportVersion=${pvRoom.exportVersion}`);
    const fileLA = fileFor(LA);
    const fileLB = fileFor(LB);
    ok(!!fileLA && !!fileLB && !!pvFile && new Set([fileLA, fileLB, pvFile]).size === 3, 'legacy: each room is its own SQLite-backed Durable Object file on disk');

    // ───────── phase 2: stop, inject authentic v2 storage + due alarms, strip exportVersion ─────────
    await stop();
    const due = Date.now() + 12000;
    const setCode = (raw, code) => JSON.stringify({ ...JSON.parse(raw), code });
    const expected = {
      [LA]: [['room', setCode(V2.lobby.room, LA)]],
      [LB]: [
        ['room', setCode(V2.running.room, LB)],
        ['game', V2.running.game],
      ],
    };
    await writeRows(fileLA, expected[LA], due);
    await writeRows(fileLB, expected[LB], due);
    await patchRoomRow(pvFile, (r) => {
      delete r.exportVersion;
    });
    for (const code of [LA, LB]) before[code] = digest(kvRows(fileFor(code)));

    // Pass 6 corrupt-save reproductions, built from real persisted v3 rows (never from a mock), aged past 6 h, alarm due.
    const aged = String(Date.now() - 7 * 3600 * 1000);
    const withRows = (file, edit) => {
      const rows = new Map(kvRows(file).map((r) => [r.k, r.v]));
      edit(rows);
      return [...rows.entries()];
    };
    const fileCA = fileFor(CA);
    const fileCB = fileFor(CB);
    const filePL = fileFor(PL);
    const filePA = fileFor(PA);
    const startedRoomRaw = JSON.parse(kvRows(fileCA).find((r) => r.k === 'room').v);
    ok(startedRoomRaw.status === 'playing' && kvRows(fileCA).some((r) => r.k === 'game'), 'corrupt saves: the base room for Case A is a real started v3 match with a persisted game', `status=${startedRoomRaw.status}`);
    const plan = {
      [CA]: [fileCA, withRows(fileCA, (m) => { const r = JSON.parse(m.get('room')); delete r.status; m.set('room', JSON.stringify(r)); m.set('touched', aged); })],
      [CB]: [fileCB, withRows(fileCB, (m) => { const r = JSON.parse(m.get('room')); r.seats[1] = null; m.set('room', JSON.stringify(r)); m.set('touched', aged); })],
      [PL]: [filePL, withRows(filePL, (m) => m.set('touched', aged))],
      [PA]: [filePA, withRows(filePA, (m) => m.set('touched', aged))],
    };
    // Pass 7: Case C (status flipped to lobby, genuine Turn 1 game kept) and Case D (game.players[0] = null).
    const fileCC = fileFor(CC);
    const fileCD = fileFor(CD);
    const genuineCC = kvRows(fileCC).find((r) => r.k === 'room').v;
    plan[CC] = [fileCC, withRows(fileCC, (m) => { const r = JSON.parse(m.get('room')); r.status = 'lobby'; m.set('room', JSON.stringify(r)); m.set('touched', aged); })];
    plan[CD] = [fileCD, withRows(fileCD, (m) => { const g = JSON.parse(m.get('game')); g.players[0] = null; m.set('game', JSON.stringify(g)); m.set('touched', aged); })];
    // Pass 8: Case E (game.standings[0].player = game.players.length on a real Turn 2 room) and Case F (hex `touched` on an
    // unstarted idle lobby with no sockets).
    const fileCE = fileFor(CE);
    const fileCF = fileFor(CF);
    const hexTouched = '0x' + (Date.now() - 7 * 3600 * 1000).toString(16);
    const genuineCE = JSON.parse(kvRows(fileCE).find((r) => r.k === 'game').v);
    plan[CE] = [fileCE, withRows(fileCE, (m) => { const g = JSON.parse(m.get('game')); g.standings[0].player = g.players.length; m.set('game', JSON.stringify(g)); m.set('touched', aged); })];
    plan[CF] = [fileCF, withRows(fileCF, (m) => m.set('touched', hexTouched))];
    for (const [file, rows] of Object.values(plan)) await writeRows(file, rows, due);
    for (const code of [CA, CB, PA, CC, CD, CE, CF]) before[code] = digest(kvRows(plan[code][0]));
    {
      const rowOf = (code, k) => JSON.parse(plan[code][1].find(([key]) => key === k)[1]);
      const gC = rowOf(CC, 'game');
      ok(JSON.parse(genuineCC).status === 'playing' && rowOf(CC, 'room').status === 'lobby' && gC.phase === 'planning' && gC.turn === 1 && plan[CC][1].map(([k]) => k).sort().join() === 'game,room,touched' && alarmPending(fileCC), 'Pass 7 Case C: injected exactly a genuine started room flipped to status lobby, with its genuine Turn 1 planning game row, aged touched (7 h) and a due alarm', `status=${rowOf(CC, 'room').status} phase=${gC.phase} turn=${gC.turn} rows=${kvRows(fileCC).length}`);
      ok(rowOf(CD, 'game').players[0] === null && rowOf(CD, 'room').status === 'playing' && plan[CD][1].map(([k]) => k).sort().join() === 'game,room,touched' && alarmPending(fileCD), 'Pass 7 Case D: injected exactly a started v3 room whose game.players[0] is null, with aged touched (7 h) and a due alarm', `player0Null=${rowOf(CD, 'game').players[0] === null} rows=${kvRows(fileCD).length}`);
    }
    {
      const rowOf = (code, k) => JSON.parse(plan[code][1].find(([key]) => key === k)[1]);
      const gE = rowOf(CE, 'game');
      ok(genuineCE.turn === 2 && gE.turn === 2 && gE.players.length === 4 && gE.standings[0].player === gE.players.length && rowOf(CE, 'room').status === 'playing' && rowOf(CE, 'room').lastResolved === 1 && plan[CE][1].map(([k]) => k).sort().join() === 'game,room,touched' && alarmPending(fileCE), 'Pass 8 Case E: injected exactly a genuine Turn 2 room (one resolution) whose game.standings[0].player = game.players.length (only that field changed), aged touched (7 h) and a due alarm', `turn=${gE.turn} standing0=${gE.standings[0].player} players=${gE.players.length} rows=${kvRows(fileCE).length}`);
      const rF = rowOf(CF, 'room');
      ok(rF.status === 'lobby' && plan[CF][1].map(([k]) => k).sort().join() === 'room,touched' && !plan[CF][1].some(([k]) => k === 'game') && plan[CF][1].find(([k]) => k === 'touched')[1] === hexTouched && /^0x[0-9a-f]+$/.test(hexTouched) && alarmPending(fileCF), 'Pass 8 Case F: injected an unstarted lobby (no sockets) whose touched text is 0x-hex of a time 7 h ago, with a due alarm', `status=${rF.status} rows=${kvRows(fileCF).length} touchedIsHex=${/^0x[0-9a-f]+$/.test(hexTouched)}`);
    }
    ok(CA && CB && PL && PA && [CA, CB, PL, PA].every((c) => alarmPending(plan[c][0])), 'corrupt saves: Case A, Case B, a valid idle lobby and a valid active match each hold aged touched (7 h) and a due alarm before the restart');
    ok(!('status' in JSON.parse(plan[CA][1].find(([k]) => k === 'room')[1])) && plan[CA][1].some(([k]) => k === 'game') && plan[CA][1].some(([k]) => k === 'touched') && JSON.parse(plan[CB][1].find(([k]) => k === 'room')[1]).seats[1] === null, 'corrupt saves: injected exactly Case A (room.status removed; game, history and touched kept) and Case B (room.seats[1] = null)');
    ok(alarmPending(fileLA) && alarmPending(fileLB), 'legacy: both v2 Durable Objects hold a due alarm before the restart (the cleanup alarm v2 itself scheduled)', `lobbyAlarm=${alarmPending(fileLA)} runningAlarm=${alarmPending(fileLB)}`);
    ok(before[LA] === digest(expected[LA].map(([k, v]) => ({ k, v }))) && before[LB] === digest(expected[LB].map(([k, v]) => ({ k, v }))), 'legacy: the injected rows are exactly the authentic v2 records (lobby: room only; running match: room + game with tick 200)', `lobbyRows=${kvRows(fileLA).length} runningRows=${kvRows(fileLB).length}`);
    ok(JSON.parse(expected[LB][1][1]).tick === 200 && 'speed' in JSON.parse(expected[LB][0][1]) && 'acc' in JSON.parse(expected[LB][0][1]), 'legacy: the injected v2 match is a real-time record (speed, acc, tick)');

    // ───────── phase 3: restart; the alarms are due; probe every route ─────────
    await start();
    for (const code of [LA, LB]) {
      const sum = await get(`/api/rooms/${code}`);
      ok(sum.status === 410 && sum.body?.legacy === true && sum.body?.code === 'legacy_room' && sum.body?.error === MESSAGE && /json/.test(sum.headers.get('content-type') ?? ''), `legacy ${code === LA ? 'lobby' : 'running match'}: GET /api/rooms/:code answers HTTP 410 legacy_room with the older-version message`, `http=${sum.status} legacy=${sum.body?.legacy} code=${sum.body?.code}`);
      const exp = await get(`/api/rooms/${code}/export`);
      ok(exp.status === 410 && exp.body?.legacy === true && exp.body?.code === 'legacy_room' && exp.body?.error === 'Legacy v2 rooms cannot be exported in v3.', `legacy ${code === LA ? 'lobby' : 'running match'}: GET /api/rooms/:code/export answers HTTP 410 legacy_room`, `http=${exp.status}`);
      const up = await rawUpgradeStatus(code);
      ok(up.status === 410 && !up.upgraded, `legacy ${code === LA ? 'lobby' : 'running match'}: a WebSocket upgrade to /ws/rooms/:code answers HTTP 410 and never upgrades`, `http=${up.status} upgraded=${up.upgraded}`);
      const init = await get(`/__do/${code}/init?code=${code}`, { method: 'POST' });
      ok(init.status === 409 && init.body?.error === 'Room exists', `legacy ${code === LA ? 'lobby' : 'running match'}: the Durable Object's POST /init answers HTTP 409 (the Worker would draw another code)`, `http=${init.status}`);
    }
    // Pass 6: both corrupt saves are isolated (410/410/410/409, never 500).
    for (const [code, label] of [[CA, 'Case A (started v3 room missing room.status)'], [CB, 'Case B (v3 lobby with room.seats[1] = null)'], [CC, 'Case C (status lobby + genuine Turn 1 game row)'], [CD, 'Case D (game.players[0] = null)'], [CE, 'Case E (Turn 2 room, game.standings[0].player = game.players.length)']]) {
      const sum = await get(`/api/rooms/${code}`);
      const exp = await get(`/api/rooms/${code}/export`);
      const up = await rawUpgradeStatus(code);
      const init = await get(`/__do/${code}/init?code=${code}`, { method: 'POST' });
      ok(sum.status === 410 && exp.status === 410 && up.status === 410 && !up.upgraded && init.status === 409, `corrupt save ${label}: /summary 410, /export 410, /ws 410 (no upgrade), /init 409, never 500`, `summary=${sum.status} export=${exp.status} ws=${up.status} init=${init.status}`);
    }
    {
      const sumF = await get(`/api/rooms/${CF}`);
      ok(sumF.status === 200 && sumF.body?.status === 'lobby' && sumF.body?.turn === 0, 'Pass 8 Case F: before its due alarm, the hex-touched lobby answers /summary 200 (a valid unstarted lobby)', `http=${sumF.status}`);
    }
    // A brand-new code on the same running build is a normal v3 room.
    const fresh = await get('/api/rooms', { method: 'POST' });
    ok(fresh.status === 201 && ![LA, LB].includes(fresh.body?.code), 'legacy: creating a room through the Worker on the same instance still yields a fresh v3 room (HTTP 201)', `http=${fresh.status}`);
    // The injected alarms fire (and a v2 room is never purged, advanced or rescheduled).
    let consumed = false;
    for (let i = 0; i < 80 && !consumed; i++) {
      consumed = !alarmPending(fileLA) && !alarmPending(fileLB) && !alarmPending(fileCA) && !alarmPending(fileCB) && !alarmPending(fileCC) && !alarmPending(fileCD) && !alarmPending(fileCE) && !alarmPending(fileCF);
      if (!consumed) await sleep(500);
    }
    if (!consumed && process.env.LEGACY_DEBUG) {
      for (const f of [fileLA, fileLB]) {
        const d = new DatabaseSync(join(doDir, f), { readOnly: true });
        console.log('DEBUG alarm row', f.slice(0, 6), JSON.stringify(d.prepare('SELECT key, CAST(value AS TEXT) AS v FROM _cf_METADATA').all()), 'now(ns)', Date.now() * 1e6);
        d.close();
      }
    }
    ok(consumed, 'legacy: the due alarms on both v2 Durable Objects fired and were not rescheduled (no purge cycle, no simulation)', `consumed=${consumed}`);
    ok(digest(kvRows(fileLA)) === before[LA] && digest(kvRows(fileLB)) === before[LB], 'legacy: after restore, /summary, /export, /ws, /init and the fired alarm every SQLite kv row is byte-for-byte identical (SHA-256 per row; no deleteAll, no touched row, no tick)', `lobbyIntact=${digest(kvRows(fileLA)) === before[LA]} runningIntact=${digest(kvRows(fileLB)) === before[LB]}`);

    ok(digest(kvRows(fileCA)) === before[CA] && digest(kvRows(fileCB)) === before[CB], 'corrupt saves: after the routes and the fired due alarm, every SQLite kv row of Case A (room, game, touched) and Case B is byte-for-byte identical (SHA-256 per row; no deleteAll)', `caseA=${digest(kvRows(fileCA)) === before[CA]} caseB=${digest(kvRows(fileCB)) === before[CB]} rowsA=${kvRows(fileCA).length} rowsB=${kvRows(fileCB).length}`);
    ok(digest(kvRows(fileCC)) === before[CC] && digest(kvRows(fileCD)) === before[CD], 'Pass 7: after the routes and the fired due alarm, every SQLite kv row of Case C (lobby + Turn 1 game) and Case D (players[0] = null) is byte-for-byte identical (SHA-256 per row; no deleteAll)', `caseC=${digest(kvRows(fileCC)) === before[CC]} caseD=${digest(kvRows(fileCD)) === before[CD]}`);
    {
      const sumE = await get(`/api/rooms/${CE}`);
      const sumF = await get(`/api/rooms/${CF}`);
      const kvTable = new DatabaseSync(join(doDir, fileCF), { readOnly: true });
      let kvExists = false;
      try {
        kvExists = kvTable.prepare("SELECT count(*) AS n FROM sqlite_master WHERE type = 'table' AND name = 'kv'").get().n === 1;
      } finally {
        kvTable.close();
      }
      ok(digest(kvRows(fileCE)) === before[CE] && kvRows(fileCE).map((r) => r.k).sort().join() === 'game,room,touched' && sumE.status === 410, 'Pass 8 Case E: after the routes and the fired due alarm, all three SQLite rows (room, game, touched) are byte-for-byte identical and the room still answers 410 (not 404)', `intact=${digest(kvRows(fileCE)) === before[CE]} http=${sumE.status}`);
      ok(sumF.status === 200 && sumF.body?.status === 'lobby' && kvExists && digest(kvRows(fileCF)) === before[CF] && kvRows(fileCF).find((r) => r.k === 'touched').v === hexTouched && kvRows(fileCF).map((r) => r.k).sort().join() === 'room,touched', 'Pass 8 Case F: after the real alarm fired, /summary STILL answers 200 (not 404), the kv table exists, and the room and hex touched rows are byte-for-byte identical (nothing purged, nothing rewritten)', `http=${sumF.status} kvTable=${kvExists} intact=${digest(kvRows(fileCF)) === before[CF]}`);
      ok(!alarmPending(fileCF), 'Pass 8 Case F: the alarm was consumed and not rescheduled (no purge loop on a corrupt clock)');
    }
    ok([fileCC, fileCD].every((f) => kvRows(f).map((r) => r.k).sort().join() === 'game,room,touched'), 'Pass 7: Case C and Case D each still have all three SQLite rows (room, game, touched)', `rowsC=${kvRows(fileCC).length} rowsD=${kvRows(fileCD).length}`);
    {
      const c3 = await get(`/api/rooms/${CC}`);
      ok(c3.status === 410 && c3.body?.legacy === true && c3.body?.error === MESSAGE, 'Pass 7 Case C: still answers 410 legacy_room after the alarm (the Turn 1 world was not wiped; it is not a 404)', `http=${c3.status}`);
    }
    ok(kvRows(fileCA).length === 3 && kvRows(fileCA).map((r) => r.k).sort().join() === 'game,room,touched', 'corrupt saves: Case A still has all three SQLite rows (room, game, touched)');
    {
      // Valid rooms keep their normal housekeeping: the idle v3 lobby is purged, the active match survives and re-arms.
      let settled = false;
      for (let i = 0; i < 60 && !settled; i++) {
        settled = (await get(`/api/rooms/${PL}`)).status === 404;
        if (!settled) await sleep(500);
      }
      const lobbyGone = (await get(`/api/rooms/${PL}`)).status === 404;
      const act = await get(`/api/rooms/${PA}`);
      ok(lobbyGone, 'valid rooms: an abandoned idle v3 lobby (7 h, nobody connected) is still purged by its due alarm (HTTP 404)', `http=${(await get(`/api/rooms/${PL}`)).status}`);
      ok(act.status === 200 && act.body?.status === 'playing' && act.body?.turn === 1 && digest(kvRows(filePA)) === before[PA], 'valid rooms: an active v3 match with 7 h idle survives its due alarm (HTTP 200, playing, Turn 1, kv rows identical)', `http=${act.status} status=${act.body?.status} turn=${act.body?.turn}`);
      ok(alarmPending(filePA), 'valid rooms: the surviving active match re-armed its housekeeping alarm');
    }

    // ───────── export guard on the real running path ─────────
    {
      const exp = await get(`/api/rooms/${PV}/export`);
      ok(exp.status === 409 && exp.body?.ok === false && exp.body?.code === 'incompatible_ruleset' && exp.body?.error === 'This match started under an older ruleset and cannot be exported as version 5.' && !exp.headers.get('content-disposition'), 'export guard: a room persisted before exportVersion existed answers HTTP 409 incompatible_ruleset, not a version-5 file of historical hashes', `http=${exp.status} code=${exp.body?.code}`);
      const sum = await get(`/api/rooms/${PV}`);
      ok(sum.status === 200 && sum.body?.turn === 2 && sum.body?.status === 'playing', 'export guard: that room still resumes (summary 200, Turn 2, playing)', `http=${sum.status} turn=${sum.body?.turn}`);
      const s = seat(PV, pvSeat);
      const w = await s.hello('Ada');
      const st = await s.next((m) => m.t === 'state');
      ok(w.seat === 0 && st.turn === 2, 'export guard: its seat reclaims over the real protocol and sees Turn 2', `seat=${w.seat} turn=${st.turn}`);
      s.send({ t: 'draft', turn: 2, revision: 1, orders: [{ t: 'borrow' }] });
      await s.next((m) => m.t === 'draftAck' && m.revision === 1);
      s.send({ t: 'ready', turn: 2, revision: 1, epoch: 0 });
      const res = await s.next((m) => m.t === 'resolved');
      s.close();
      await sleep(300);
      const exp2 = await get(`/api/rooms/${PV}/export`);
      ok(res.turn === 3 && exp2.status === 409 && exp2.body?.code === 'incompatible_ruleset', 'export guard: the pre-v5 room keeps playing (Turn 3 resolved) and its export stays refused', `turn=${res.turn} http=${exp2.status}`);
    }

    // ───────── phase 4: real Chrome ─────────
    const c = await ctx('legacy-chrome', { video: true });
    const P = await openPage(c, 'legacy-lobby');
    await P.addInitScript(() => {
      window.__wsUrls = [];
      const W = window.WebSocket;
      window.WebSocket = new Proxy(W, {
        construct(target, args) {
          window.__wsUrls.push(String(args[0]).replace(/^wss?:\/\/[^/]+/, ''));
          return new target(...args);
        },
      });
    });
    const seed = (page, code, other) =>
      page.evaluate(([a, b]) => {
        const rec = (id) => JSON.stringify({ id, at: 1, beat: 0, tab: 'old' });
        localStorage.setItem(`mercadia:pid:${a}`, rec('legacy-seat-token-a'));
        sessionStorage.setItem(`mercadia:pid:${a}`, 'legacy-seat-token-a');
        localStorage.setItem(`mercadia:pid:${b}`, rec('other-room-seat-token'));
        sessionStorage.setItem(`mercadia:pid:${b}`, 'other-room-seat-token');
      }, [code, other]);
    const tokenState = (page, code, other) =>
      page.evaluate(([a, b]) => ({ legacyLocal: localStorage.getItem(`mercadia:pid:${a}`) !== null, legacySession: sessionStorage.getItem(`mercadia:pid:${a}`) !== null, otherLocal: localStorage.getItem(`mercadia:pid:${b}`) !== null, otherSession: sessionStorage.getItem(`mercadia:pid:${b}`) !== null }), [code, other]);
    const otherCode = PV;

    await P.goto(`${ORIGIN}/?dev=1`);
    await seed(P, LA, otherCode);
    const seeded = await tokenState(P, LA, otherCode);
    await P.goto(`${ORIGIN}/?dev=1&room=${LA}`);
    await P.waitForFunction((m) => document.body.innerText.includes(m) && window.__mercadia?.view.status.text === m, MESSAGE, { timeout: 20000 });
    const wsAtNotice = await P.evaluate(() => window.__wsUrls.length);
    await sleep(7000); // a reconnect storm would have retried at 0.5, 1.5 and 3.5 s by now
    const wsLater = await P.evaluate(() => window.__wsUrls.length);
    const toks = await tokenState(P, LA, otherCode);
    const dom = await P.evaluate(() => ({ create: !!Array.from(document.querySelectorAll('button')).find((b) => b.textContent.trim() === 'Create New Room'), back: !!Array.from(document.querySelectorAll('button')).find((b) => /^Back to title$/i.test(b.textContent.trim())), alert: !!document.querySelector('[role="alert"]') }));
    ok(seeded.legacyLocal && seeded.legacySession && seeded.otherLocal && seeded.otherSession, 'legacy chrome: the browser held seat tokens for the legacy room and for another room', JSON.stringify(seeded));
    ok(wsAtNotice === 1 && wsLater === 1, 'legacy chrome: Chrome opened exactly one WebSocket (refused with 410) and made zero reconnect attempts in the 7 s after the notice (no reconnect storm)', `atNotice=${wsAtNotice} later=${wsLater}`);
    ok(!toks.legacyLocal && !toks.legacySession && toks.otherLocal && toks.otherSession, 'legacy chrome: ONLY the legacy room\'s token left localStorage and sessionStorage; the other room\'s token is untouched', `legacyCleared=${!toks.legacyLocal && !toks.legacySession} otherRoomPreserved=${toks.otherLocal && toks.otherSession}`);
    ok(dom.create && dom.back && dom.alert, 'legacy chrome: the error view shows the older-version message with Create New Room and Back to title buttons', JSON.stringify(dom));
    await sleep(400);
    await shot(P, '42-legacy-v2-room-410-create-new-room');
    for (const [w, hgt, name] of [[1024, 768, '43-legacy-v2-room-410-1024x768'], [390, 844, '44-legacy-v2-room-410-390x844']]) {
      await P.setViewportSize({ width: w, height: hgt });
      await sleep(500);
      const fit = await P.evaluate(() => {
        const b = Array.from(document.querySelectorAll('button')).find((x) => x.textContent.trim() === 'Create New Room');
        const r = b?.getBoundingClientRect();
        return { inView: !!r && r.left >= 0 && r.right <= innerWidth && r.top >= 0 && r.bottom <= innerHeight, h: r ? Math.round(r.height) : 0, overflowX: document.documentElement.scrollWidth > innerWidth + 1 };
      });
      ok(fit.inView && fit.h >= 40 && !fit.overflowX, `legacy chrome (${w}×${hgt}): Create New Room is on screen, tappable, and nothing overflows horizontally`, JSON.stringify(fit));
      await shot(P, name);
    }
    await P.setViewportSize({ width: 1440, height: 900 });
    await sleep(300);
    // Create New Room: a real POST /api/rooms, then the working v3 lobby.
    const creates = [];
    P.on('request', (r) => {
      if (r.method() === 'POST' && /\/api\/rooms$/.test(r.url())) creates.push(r.url());
    });
    await P.getByRole('button', { name: 'Create New Room' }).click();
    await P.waitForURL((u) => new URL(u).searchParams.get('room') && new URL(u).searchParams.get('room') !== LA, { timeout: 15000 });
    const newCode = new URL(P.url()).searchParams.get('room');
    await P.getByRole('button', { name: /Start match/ }).waitFor({ timeout: 15000 });
    await sleep(500);
    await shot(P, '45-legacy-create-new-room-fresh-v3-lobby');
    ok(creates.length === 1 && /^[A-Z]{4}$/.test(newCode) && ![LA, LB].includes(newCode), 'legacy chrome: Create New Room made one POST /api/rooms and opened a different, fresh v3 room lobby', `posts=${creates.length} newRoomDiffers=${newCode !== LA}`);
    await P.getByRole('button', { name: /Start match/ }).click();
    await P.waitForFunction(() => window.__mercadia?.phase === 'planning' && window.__mercadia.turn === 1, null, { timeout: 20000 });
    await sleep(900);
    const a = await M(P);
    await endBtn(P).click();
    await P.waitForFunction(() => window.__mercadia.turn === 2, null, { timeout: 20000 });
    await sleep(700);
    await shot(P, '46-legacy-create-new-room-fresh-v3-turn-2');
    const b2 = await M(P);
    ok(a.seat === 0 && a.turn === 1 && b2.turn === 2 && b2.resolutions === 1, 'legacy chrome: the fresh room is fully playable: started Turn 1, End Turn resolved it exactly once to Turn 2', `seat=${a.seat} turn ${a.turn}->${b2.turn}`);
    pages.find((r) => r.page === P).csp = await P.evaluate(() => window.__csp ?? []);

    // The running v2 match, in the same browser context.
    const Q = await openPage(c, 'legacy-running');
    await Q.goto(`${ORIGIN}/?dev=1`);
    await seed(Q, LB, otherCode);
    await Q.goto(`${ORIGIN}/?dev=1&room=${LB}`);
    await Q.waitForFunction((m) => document.body.innerText.includes(m), MESSAGE, { timeout: 20000 });
    await sleep(4000);
    const qt = await tokenState(Q, LB, otherCode);
    ok(!qt.legacyLocal && !qt.legacySession && qt.otherLocal && qt.otherSession && (await Q.getByRole('button', { name: 'Create New Room' }).count()) === 1, 'legacy chrome (v2 running match): the same notice and Create New Room appear, only that room\'s token is dropped', `legacyCleared=${!qt.legacyLocal && !qt.legacySession} otherRoomPreserved=${qt.otherLocal && qt.otherSession}`);
    await shot(Q, '47-legacy-v2-running-match-410');
    pages.find((r) => r.page === Q).csp = await Q.evaluate(() => window.__csp ?? []);

    // Pass 7 Case D in real Chrome: a null nested player must be a graceful older-version notice, never an uncaught error.
    {
      const D = await openPage(c, 'legacy-chrome-case-d');
      await D.goto(`${ORIGIN}/?dev=1`);
      await D.goto(`${ORIGIN}/?dev=1&room=${CD}`);
      await D.waitForFunction((m) => document.body.innerText.includes(m), MESSAGE, { timeout: 20000 });
      await sleep(3000);
      const dd = await D.evaluate(() => ({ create: !!Array.from(document.querySelectorAll('button')).find((b) => b.textContent.trim() === 'Create New Room'), alert: !!document.querySelector('[role="alert"]') }));
      await shot(D, '49-case-d-null-player-410-graceful-notice');
      const dIssues = pages.find((r) => r.page === D).issues;
      const uncaught = dIssues.filter((i) => /^pageerror:/.test(i));
      ok(dd.create && dd.alert && uncaught.length === 0, 'Pass 7 Case D chrome: game.players[0] = null shows the older-version notice with Create New Room and zero uncaught page errors', `create=${dd.create} alert=${dd.alert} uncaught=${uncaught.length}`);
      ok(digest(kvRows(fileCD)) === before[CD], 'Pass 7 Case D chrome: after Chrome opened the room, its three kv rows are still byte-for-byte identical', `intact=${digest(kvRows(fileCD)) === before[CD]}`);
      pages.find((r) => r.page === D).csp = await D.evaluate(() => window.__csp ?? []);
      await D.close(); // its proof is screenshot 49 and the checks above; closing it keeps the media directory within 64 files
    }

    // Pass 8 Case E in real Chrome: the real seat reclaims a room whose standings index is out of range. Graceful notice,
    // zero uncaught errors, only that room's token dropped, SQLite untouched.
    {
      const E = await openPage(c, 'legacy-chrome-case-e');
      await E.goto(`${ORIGIN}/?dev=1`);
      await E.evaluate(([code, other, id]) => {
        localStorage.setItem(`mercadia:pid:${code}`, JSON.stringify({ id, at: 1, beat: 0, tab: 'old' }));
        sessionStorage.setItem(`mercadia:pid:${code}`, id);
        localStorage.setItem(`mercadia:pid:${other}`, JSON.stringify({ id: 'other-room-seat-token', at: 1, beat: 0, tab: 'old' }));
        sessionStorage.setItem(`mercadia:pid:${other}`, 'other-room-seat-token');
      }, [CE, otherCode, ceSeat]);
      const eSeeded = await tokenState(E, CE, otherCode);
      await E.goto(`${ORIGIN}/?dev=1&room=${CE}`);
      await E.waitForFunction((m) => document.body.innerText.includes(m), MESSAGE, { timeout: 20000 });
      await sleep(3000);
      const ee = await E.evaluate(() => ({ create: !!Array.from(document.querySelectorAll('button')).find((b) => b.textContent.trim() === 'Create New Room'), alert: !!document.querySelector('[role="alert"]') }));
      const et = await tokenState(E, CE, otherCode);
      await shot(E, '50-case-e-bad-standing-410');
      const eIssues = pages.find((r) => r.page === E).issues;
      const eUncaught = eIssues.filter((i) => /^pageerror:/.test(i));
      ok(eSeeded.legacyLocal && eSeeded.legacySession && ee.create && ee.alert && eUncaught.length === 0, 'Pass 8 Case E chrome: the real seat token reclaiming a room with game.standings[0].player = game.players.length shows the older-version notice with Create New Room and zero uncaught page errors', `create=${ee.create} alert=${ee.alert} uncaught=${eUncaught.length}`);
      ok(!et.legacyLocal && !et.legacySession && et.otherLocal && et.otherSession, 'Pass 8 Case E chrome: only that room\'s token was dropped; the other room\'s token is untouched', `legacyCleared=${!et.legacyLocal && !et.legacySession} otherRoomPreserved=${et.otherLocal && et.otherSession}`);
      ok(digest(kvRows(fileCE)) === before[CE], 'Pass 8 Case E chrome: after Chrome reclaimed the seat, the room, game and touched rows are still byte-for-byte identical (zero SQLite writes)', `intact=${digest(kvRows(fileCE)) === before[CE]}`);
      pages.find((r) => r.page === E).csp = await E.evaluate(() => window.__csp ?? []);
      await E.close(); // its proof is screenshot 50 and the checks above; closing it keeps the media directory within 64 files
    }

    // The pre-v5 room, in a real browser: Export match surfaces the notice instead of a broken download.
    const R = await openPage(c, 'legacy-pre-v5-export');
    await R.goto(`${ORIGIN}/?dev=1`);
    await R.evaluate(([code, id]) => {
      localStorage.setItem(`mercadia:pid:${code}`, JSON.stringify({ id, at: 1, beat: 0, tab: 'old' }));
      sessionStorage.setItem(`mercadia:pid:${code}`, id);
    }, [PV, pvSeat]);
    await R.goto(`${ORIGIN}/?dev=1&room=${PV}`);
    await R.waitForFunction(() => window.__mercadia?.phase === 'planning' && window.__mercadia.turn === 3 && window.__mercadia.seat === 0, null, { timeout: 20000 });
    await sleep(800);
    let downloaded = false;
    R.on('download', () => {
      downloaded = true;
    });
    await R.locator('#hud [data-act="delta"]').click();
    await R.locator('#h-drawer [data-act="export"]').waitFor({ timeout: 8000 });
    await sleep(700);
    await R.locator('#h-drawer [data-act="export"]').click();
    const notice = R.getByText(/started under an older ruleset and cannot be exported as version 5/);
    await notice.first().waitFor({ timeout: 8000 });
    await sleep(1200);
    await shot(R, '48-pre-v5-room-export-refused-notice');
    ok(!downloaded && (await notice.count()) >= 1, 'export guard chrome: Export match on the pre-v5 room shows the incompatible-ruleset notice and downloads nothing', `downloaded=${downloaded}`);
    pages.find((r) => r.page === R).csp = await R.evaluate(() => window.__csp ?? []);
    await finishCtx(c, 'legacy-v2-room-create-new-room');

    // After everything the browser did, the v2 bytes are still untouched.
    ok(digest(kvRows(fileLA)) === before[LA] && digest(kvRows(fileLB)) === before[LB], 'legacy: after the Chrome session (notice, token drop, Create New Room) both v2 Durable Objects are still byte-for-byte untouched', `lobbyIntact=${digest(kvRows(fileLA)) === before[LA]} runningIntact=${digest(kvRows(fileLB)) === before[LB]}`);
    const recheck = await get(`/api/rooms/${LA}`);
    ok(recheck.status === 410, 'legacy: the lobby room still answers 410 afterwards (nothing recreated it)', `http=${recheck.status}`);
  } finally {
    await stop();
    try {
      rmSync(persist, { recursive: true, force: true });
    } catch {
      // temp dir
    }
  }
}
